//! The git patch corpus (DESIGN.md §A4.8), generated by `script/gen-patch-oracle` from the
//! pairs of the git corpus: `unified` gives `git diff --no-index`'s hunks.

use std::collections::{HashMap, HashSet};
use std::ops::Range;

use merge_core::diff::DiffOptions;
use merge_core::diff2::{Kind2, regions};
use merge_core::patch::{Scope, Titles, unified};
use merge_core::text::Text;
use serde::Deserialize;

const CORPUS: &str = include_str!("../../../fixtures/oracle/corpus.jsonl");
const PATCHES: &str = include_str!("../../../fixtures/oracle/patch-corpus.jsonl");

// From `script/gen-patch-oracle`: its PAIRS and CONTEXTS, and the git corpus's case count.
const PAIRS: usize = 2;
const CONTEXTS: [usize; 3] = [0, 1, 3];
const TRIPLES: usize = 1955;

/// git's exit code for inputs that differ.
const DIFFERENT: i32 = 1;

const TITLES: Titles<'static> = Titles { left: "a", right: "b" };
const HEADERS: &str = "--- a\n+++ b\n";

#[derive(Debug, Deserialize)]
struct Triple {
    id: String,
    base: String,
    left: String,
    right: String,
}

impl Triple {
    fn side(&self, name: &str) -> &str {
        match name {
            "base" => &self.base,
            "left" => &self.left,
            "right" => &self.right,
            other => panic!("no side named {other}"),
        }
    }
}

#[derive(Debug, Deserialize)]
struct Patch {
    id: String,
    before: String,
    after: String,
    context: usize,
    exit: i32,
    hunks: String,
}

fn triples() -> HashMap<String, Triple> {
    CORPUS
        .lines()
        .map(|line| serde_json::from_str::<Triple>(line).expect("corpus line parses"))
        .map(|t| (t.id.clone(), t))
        .collect()
}

fn patches() -> Vec<Patch> {
    PATCHES.lines().map(|line| serde_json::from_str(line).expect("patch line parses")).collect()
}

fn text(s: &str) -> Text {
    Text::decode(s.as_bytes()).expect("corpus text decodes")
}

#[test]
fn the_patch_corpus_covers_every_triple_pair_and_context() {
    let patches = patches();
    assert_eq!(patches.len(), TRIPLES * PAIRS * CONTEXTS.len());
    let triples = triples();
    assert_eq!(triples.len(), TRIPLES);
    let keys: HashSet<(&str, &str, usize)> =
        patches.iter().map(|p| (p.id.as_str(), p.before.as_str(), p.context)).collect();
    assert_eq!(keys.len(), patches.len(), "each case is unique");
    assert!(patches.iter().all(|p| triples.contains_key(&p.id)), "each case names a triple");
    let differing = patches.iter().filter(|p| p.exit == DIFFERENT).count();
    assert!(differing > patches.len() / 2, "most pairs differ: {differing}");
}

/// The line ranges of git's `-U0` hunks, from their headers, from 0 with the end excluded.
/// An empty range's header names the line before it.
fn git_ranges(hunks: &str) -> Vec<[Range<usize>; 2]> {
    let range = |field: &str| {
        let (start, count) = field.split_once(',').unwrap_or((field, "1"));
        let (start, count): (usize, usize) =
            (start.parse().expect("a line number"), count.parse().expect("a line count"));
        let from = if count == 0 { start } else { start - 1 };
        from..from + count
    };
    hunks
        .lines()
        .filter_map(|line| line.strip_prefix("@@ -"))
        .map(|header| {
            let mut fields = header.split(' ');
            let left = fields.next().expect("a left range");
            let right = fields.next().and_then(|f| f.strip_prefix('+')).expect("a right range");
            [range(left), range(right)]
        })
        .collect()
}

/// Pairs on which triad's two-way diff, imara-diff's histogram with the indent heuristic
/// (spec §4.4), picks other hunks than git's histogram. A measured count, held so a change
/// to either diff shows; the patch of such a pair cannot match git's.
const DIFF_DIVERGENCES: usize = 58;

/// Where triad's diff gives git's hunks, `unified` gives git's patch byte for byte at every
/// context size, function names included.
#[test]
fn unified_gives_gits_patch_wherever_the_diffs_agree() {
    let triples = triples();
    let opts = DiffOptions::default();
    let patches = patches();
    let hunks_at_0: HashMap<(&str, &str), Vec<[Range<usize>; 2]>> = patches
        .iter()
        .filter(|p| p.context == 0)
        .map(|p| ((p.id.as_str(), p.before.as_str()), git_ranges(&p.hunks)))
        .collect();
    let mut divergent = HashSet::new();
    let mut failures = Vec::new();
    for case in &patches {
        let triple = &triples[&case.id];
        let (before, after) = (text(triple.side(&case.before)), text(triple.side(&case.after)));
        let found = regions(&before, &after, &opts);
        let ours: Vec<[Range<usize>; 2]> = found
            .iter()
            .filter(|r| r.kind == Kind2::Changed)
            .map(|r| [r.left.clone(), r.right.clone()])
            .collect();
        assert_eq!(ours.is_empty(), case.exit != DIFFERENT, "{} exit", case.id);
        let pair = (case.id.as_str(), case.before.as_str());
        if ours != hunks_at_0[&pair] {
            divergent.insert(pair);
            continue;
        }
        let patch = unified(&before, &after, &found, case.context, Scope::File, TITLES);
        let expected =
            if case.hunks.is_empty() { String::new() } else { format!("{HEADERS}{}", case.hunks) };
        if patch != expected {
            failures.push(format!(
                "{} {}→{} -U{}:\n--- git\n{expected}--- triad\n{patch}",
                case.id, case.before, case.after, case.context
            ));
        }
    }
    assert!(failures.is_empty(), "{} cases differ:\n{}", failures.len(), failures.join("\n"));
    assert_eq!(divergent.len(), DIFF_DIVERGENCES, "pairs whose diffs differ from git's");
}
